                int nested, char *name, char ***popts, int *aopts, int *nopts)
{
        bool global = false;
        bool stdin_occupied = false;
        char *string;
        FILE *f;
        char *p;
        int ret = 0, stonewall;
        int first_sect = 1;
        int skip_fgets = 0;
        int inside_skip = 0;
        char **opts;
        int i, alloc_opts, num_opts;

        dprint(FD_PARSE, "Parsing ini file %s\n", file);
        assert(td || !nested);

        if (is_buf)
                f = NULL;
        else {
                if (!strcmp(file, "-")) {
                        f = stdin;
                        stdin_occupied = true;
                } else
                        f = fopen(file, "r");

                if (!f) {
                        int __err = errno;

                        log_err("fio: unable to open '%s' job file\n", file);
                        if (td)
                                td_verror(td, __err, "job file open");
                        return 1;
                }
        }

        string = malloc(OPT_LEN_MAX);

        /*
         * it's really 256 + small bit, 280 should suffice
         */
        if (!nested) {
                name = malloc(280);
                memset(name, 0, 280);
        }

        opts = NULL;
        if (nested && popts) {
                opts = *popts;
                alloc_opts = *aopts;
                num_opts = *nopts;
